import { useState, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import {
  Plus, MapPin, Store as StoreIcon, Sparkles, Eye,
  Building2, Globe, TrendingUp, AlertTriangle, Search,
  ChevronLeft, ChevronRight, Hash,
} from "lucide-react";
import {
  Card, PageHeader, Button, SearchInput, CountUp, MiniSparkline,
  Modal, Input, Badge,
} from "@/components/ui";
import { useAllStores, useAllInspections, calculateStoreScore } from "@/lib/data";
import { useStore } from "@/store/useStore";
import { cn } from "@/lib/utils";

const REGIONS = ["全部", "上海", "杭州", "苏州", "南京", "深圳"];
const PAGE_SIZE = 8;

function scoreBg(score: number) {
  if (score >= 90) return "bg-emerald-50 text-emerald-700 border-emerald-200";
  if (score >= 75) return "bg-brand-50 text-brand-700 border-brand-200";
  if (score >= 60) return "bg-amber-50 text-amber-700 border-amber-200";
  return "bg-red-50 text-red-700 border-red-200";
}

// 给门店生成稳定的迷你趋势数据
function sparkFor(id: string, base: number) {
  const seed = id.charCodeAt(id.length - 1);
  return Array.from({ length: 8 }, (_, i) =>
    base + Math.sin((i + seed) * 0.7) * 6 + (i % 3) * 1.2
  );
}

// 生成分页页码（智能省略号：始终显示首末页 + 当前页±1）
function getPageNumbers(current: number, total: number): (number | "...")[] {
  if (total <= 7) {
    return Array.from({ length: total }, (_, i) => i + 1);
  }
  const pages: (number | "...")[] = [1];
  const left = Math.max(2, current - 1);
  const right = Math.min(total - 1, current + 1);
  if (left > 2) pages.push("...");
  for (let i = left; i <= right; i++) pages.push(i);
  if (right < total - 1) pages.push("...");
  pages.push(total);
  return pages;
}

interface FormState {
  name: string;
  region: string;
  address: string;
  manager: string;
  phone: string;
}

const EMPTY_FORM: FormState = {
  name: "",
  region: "上海",
  address: "",
  manager: "",
  phone: "",
};

export default function StoreList() {
  const navigate = useNavigate();
  const allStores = useAllStores();
  const allInspections = useAllInspections();
  const addStore = useStore((s) => s.addStore);

  const [keyword, setKeyword] = useState("");
  const [region, setRegion] = useState("全部");
  const [page, setPage] = useState(1);

  // 新建门店 Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [form, setForm] = useState<FormState>(EMPTY_FORM);
  const [errors, setErrors] = useState<Partial<FormState>>({});

  // 派生评分：从巡检记录计算，避免新门店 avgScore: -1 的旧字段失真
  // 门店列表、详情、Dashboard 排行调用同一函数 calculateStoreScore
  const scoreMap = useMemo(() => {
    const m = new Map<string, number | null>();
    for (const s of allStores) {
      m.set(s.id, calculateStoreScore(s.id, allInspections));
    }
    return m;
  }, [allStores, allInspections]);

  // 顶部统计数据（仅统计有评分的门店，新门店无巡检则不参与平均）
  const scoredStores = allStores.filter((s) => scoreMap.get(s.id) !== null && scoreMap.get(s.id) !== undefined);
  const total = allStores.length;
  const cityCount = new Set(allStores.map((s) => s.region)).size;
  const avg = scoredStores.length > 0
    ? Math.round(scoredStores.reduce((s, x) => s + (scoreMap.get(x.id) ?? 0), 0) / scoredStores.length)
    : 0;
  const highRisk = scoredStores.filter((s) => (scoreMap.get(s.id) ?? 100) < 70).length;

  // 过滤
  const filtered = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    return allStores.filter((s) => {
      const matchKw = !kw ||
        s.name.toLowerCase().includes(kw) ||
        s.code.toLowerCase().includes(kw);
      const matchRegion = region === "全部" || s.region === region;
      return matchKw && matchRegion;
    });
  }, [keyword, region, allStores]);

  // 分页
  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(Math.max(1, page), totalPages);
  const pageData = filtered.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);
  const pageNumbers = getPageNumbers(safePage, totalPages);

  const handleSearch = (v: string) => {
    setKeyword(v);
    setPage(1);
  };
  const handleRegion = (r: string) => {
    setRegion(r);
    setPage(1);
  };
  const goDetail = (id: string) => navigate(`/store/${id}`);

  // 校验表单
  const validate = (): boolean => {
    const errs: Partial<FormState> = {};
    if (!form.name.trim()) errs.name = "请输入门店名称";
    if (!form.region.trim()) errs.region = "请选择所在城市";
    if (!form.address.trim()) errs.address = "请输入详细地址";
    if (!form.manager.trim()) errs.manager = "请输入店长姓名";
    if (!form.phone.trim()) {
      errs.phone = "请输入联系电话";
    } else if (!/^1\d{10}$/.test(form.phone.trim())) {
      errs.phone = "请输入正确的手机号（11位）";
    }
    setErrors(errs);
    return Object.keys(errs).length === 0;
  };

  const handleSubmit = () => {
    if (!validate()) return;
    const id = addStore(form);
    setModalOpen(false);
    setForm(EMPTY_FORM);
    setErrors({});
    // 跳转到新店详情
    setTimeout(() => navigate(`/store/${id}`), 200);
  };

  const closeModal = () => {
    setModalOpen(false);
    setForm(EMPTY_FORM);
    setErrors({});
  };

  // 新建门店标记
  const isNewStore = (id: string) => id.startsWith("store-new-");

  return (
    <div className="animate-fade-in">
      <PageHeader
        title="门店管理"
        subtitle="茶小鲜 · 全国连锁食安巡检网络"
        badge={
          <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-brand-50 text-brand-700 text-[10px] font-semibold tracking-wider border border-brand-200/80">
            <Sparkles className="w-3 h-3" /> {total} STORES
          </span>
        }
        actions={
          <Button
            variant="gradient"
            size="md"
            onClick={() => setModalOpen(true)}
            icon={<Plus className="w-4 h-4" />}
          >
            新增门店
          </Button>
        }
      />

      {/* 顶部统计 */}
      <div className="grid grid-cols-4 gap-4 mb-5">
        <div className="relative overflow-hidden rounded-xl bg-white border border-ink-200/70 p-4 transition-all duration-300 hover:-translate-y-0.5 group">
          <div className="absolute top-0 left-0 right-0 h-0.5 bg-gradient-to-r from-brand-700 to-cyan-600" />
          <div className="flex items-start justify-between mb-2">
            <p className="text-[10px] text-ink-400 font-semibold tracking-widest uppercase">总门店</p>
            <div className="w-7 h-7 rounded-lg bg-gradient-to-br from-brand-700 to-cyan-600 flex items-center justify-center shadow-glow-brand">
              <StoreIcon className="w-3.5 h-3.5 text-white" />
            </div>
          </div>
          <p className="text-3xl font-bold font-display tracking-tight tabular-nums text-ink-900">
            <CountUp end={total} duration={1400} />
          </p>
          <p className="text-[11px] text-ink-400 mt-1">家在运营</p>
        </div>

        <div className="relative overflow-hidden rounded-xl bg-white border border-ink-200/70 p-4 transition-all duration-300 hover:-translate-y-0.5 group">
          <div className="absolute top-0 left-0 right-0 h-0.5 bg-gradient-to-r from-cyan-500 to-cyan-400" />
          <div className="flex items-start justify-between mb-2">
            <p className="text-[10px] text-ink-400 font-semibold tracking-widest uppercase">城市覆盖</p>
            <div className="w-7 h-7 rounded-lg bg-gradient-to-br from-cyan-500 to-cyan-600 flex items-center justify-center shadow-[0_0_12px_rgba(6,182,212,0.4)]">
              <Globe className="w-3.5 h-3.5 text-white" />
            </div>
          </div>
          <p className="text-3xl font-bold font-display tracking-tight tabular-nums text-cyan-700">
            <CountUp end={cityCount} duration={1400} />
          </p>
          <p className="text-[11px] text-ink-400 mt-1">座城市</p>
        </div>

        <div className="relative overflow-hidden rounded-xl bg-white border border-ink-200/70 p-4 transition-all duration-300 hover:-translate-y-0.5 group">
          <div className="absolute top-0 left-0 right-0 h-0.5 bg-gradient-to-r from-emerald-500 to-emerald-400" />
          <div className="flex items-start justify-between mb-2">
            <p className="text-[10px] text-ink-400 font-semibold tracking-widest uppercase">平均分</p>
            <div className="w-7 h-7 rounded-lg bg-gradient-to-br from-emerald-500 to-emerald-600 flex items-center justify-center shadow-[0_0_12px_rgba(16,185,129,0.4)]">
              <TrendingUp className="w-3.5 h-3.5 text-white" />
            </div>
          </div>
          <p className="text-3xl font-bold font-display tracking-tight tabular-nums text-emerald-600">
            <CountUp end={avg} duration={1400} />
          </p>
          <p className="text-[11px] text-ink-400 mt-1">综合得分</p>
        </div>

        <div className="relative overflow-hidden rounded-xl bg-white border border-ink-200/70 p-4 transition-all duration-300 hover:-translate-y-0.5 group">
          <div className="absolute top-0 left-0 right-0 h-0.5 bg-gradient-to-r from-red-500 to-orange-500" />
          <div className="flex items-start justify-between mb-2">
            <p className="text-[10px] text-ink-400 font-semibold tracking-widest uppercase">高风险门店</p>
            <div className="w-7 h-7 rounded-lg bg-gradient-to-br from-red-500 to-orange-500 flex items-center justify-center shadow-[0_0_12px_rgba(220,38,38,0.4)]">
              <AlertTriangle className="w-3.5 h-3.5 text-white" />
            </div>
          </div>
          <p className="text-3xl font-bold font-display tracking-tight tabular-nums text-red-600">
            <CountUp end={highRisk} duration={1400} />
          </p>
          <p className="text-[11px] text-ink-400 mt-1">家需关注</p>
        </div>
      </div>

      {/* 筛选区 */}
      <Card className="p-4 mb-5">
        <div className="flex items-center gap-4 flex-wrap">
          <div className="w-72">
            <SearchInput
              value={keyword}
              onChange={handleSearch}
              placeholder="搜索门店名称或编号..."
            />
          </div>
          <div className="flex items-center gap-2">
            <MapPin className="w-3.5 h-3.5 text-ink-400" />
            <span className="text-sm text-ink-500 font-medium">区域：</span>
            <div className="flex items-center gap-1.5">
              {REGIONS.map((r) => (
                <button
                  key={r}
                  onClick={() => handleRegion(r)}
                  className={cn(
                    "px-3 py-1 rounded-md text-xs font-medium transition-all cursor-pointer border",
                    region === r
                      ? "bg-gradient-to-r from-brand-900 to-brand-700 text-white border-transparent shadow-sm"
                      : "bg-white text-ink-500 border-ink-200 hover:border-brand-300 hover:text-brand-700"
                  )}
                >
                  {r}
                </button>
              ))}
            </div>
          </div>
          <div className="ml-auto flex items-center gap-1.5 text-xs text-ink-500">
            <Building2 className="w-3.5 h-3.5" />
            <span>共</span>
            <span className="font-semibold text-ink-700 tabular-nums">{filtered.length}</span>
            <span>家</span>
          </div>
        </div>
      </Card>

      {/* 表格 */}
      <Card className="overflow-hidden">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-gradient-to-r from-ink-50 to-ink-100/50 text-ink-500 text-xs">
              <th className="text-left px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px] w-14">#</th>
              <th className="text-left px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">门店</th>
              <th className="text-left px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">编号</th>
              <th className="text-left px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">区域</th>
              <th className="text-left px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">店长</th>
              <th className="text-center px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">平均分</th>
              <th className="text-right px-5 py-3.5 font-semibold tracking-wider uppercase text-[10px]">操作</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-ink-100/80">
            {pageData.length === 0 ? (
              <tr>
                <td colSpan={7} className="px-4 py-16 text-center">
                  <div className="flex flex-col items-center text-ink-300">
                    <Search className="w-10 h-10 mb-2" />
                    <p className="text-sm">未找到符合条件的门店</p>
                  </div>
                </td>
              </tr>
            ) : (
              pageData.map((s, idx) => (
                <tr
                  key={s.id}
                  className="group hover:bg-gradient-to-r hover:from-brand-50/40 hover:to-transparent cursor-pointer transition"
                  onClick={() => goDetail(s.id)}
                >
                  <td className="px-5 py-3.5 text-ink-400 text-xs tabular-nums">
                    {String((safePage - 1) * PAGE_SIZE + idx + 1).padStart(2, "0")}
                  </td>
                  <td className="px-5 py-3.5">
                    <div className="flex items-center gap-2.5">
                      <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-brand-700 to-cyan-600 flex items-center justify-center shrink-0 shadow-sm">
                        <StoreIcon className="w-3.5 h-3.5 text-white" />
                      </div>
                      <div className="min-w-0">
                        <div className="flex items-center gap-1.5">
                          <p className="text-ink-800 font-medium truncate">{s.name}</p>
                          {isNewStore(s.id) && (
                            <Badge variant="success" size="sm">NEW</Badge>
                          )}
                        </div>
                        <p className="text-[11px] text-ink-400 truncate">{s.address}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-5 py-3.5">
                    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md bg-ink-100/60 text-ink-600 font-mono text-[11px]">
                      <Hash className="w-3 h-3" />
                      {s.code}
                    </span>
                  </td>
                  <td className="px-5 py-3.5">
                    <span className="inline-flex items-center gap-1 text-xs text-ink-600">
                      <span className="w-1.5 h-1.5 rounded-full bg-cyan-500" />
                      {s.region}
                    </span>
                  </td>
                  <td className="px-5 py-3.5">
                    <div className="flex items-center gap-1.5">
                      <div className="w-6 h-6 rounded-full bg-gradient-to-br from-cyan-500 to-brand-700 text-white text-[10px] font-semibold flex items-center justify-center">
                        {s.manager[0]}
                      </div>
                      <span className="text-ink-600 text-xs">{s.manager}</span>
                    </div>
                  </td>
                  <td className="px-5 py-3.5">
                    <div className="flex items-center justify-center gap-2">
                      {(() => {
                        const score = scoreMap.get(s.id);
                        if (score === null || score === undefined) {
                          return <span className="text-xs text-ink-400 italic">暂无评分</span>;
                        }
                        return (
                          <>
                            <span className={cn(
                              "inline-flex items-center justify-center min-w-[44px] px-2 py-0.5 rounded-md text-sm font-bold font-display tabular-nums border",
                              scoreBg(score)
                            )}>
                              {score}
                            </span>
                            <div className="opacity-50 group-hover:opacity-100 transition-opacity">
                              <MiniSparkline
                                data={sparkFor(s.id, score)}
                                color={score >= 90 ? "#10b981" : score >= 75 ? "#1d4ed8" : score >= 60 ? "#f59e0b" : "#dc2626"}
                                width={48}
                                height={20}
                              />
                            </div>
                          </>
                        );
                      })()}
                    </div>
                  </td>
                  <td className="px-5 py-3.5 text-right">
                    <button
                      className="inline-flex items-center gap-1 px-2.5 py-1 rounded-md text-xs text-brand-600 hover:bg-brand-50 transition cursor-pointer opacity-0 group-hover:opacity-100"
                      onClick={(e) => { e.stopPropagation(); goDetail(s.id); }}
                    >
                      <Eye className="w-3.5 h-3.5" /> 查看
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>

        {/* 分页 */}
        <div className="flex items-center justify-between px-5 py-3 border-t border-ink-100/80 bg-gradient-to-r from-ink-50/30 to-transparent">
          <div className="text-xs text-ink-500 tabular-nums">
            {filtered.length === 0 ? (
              <span>暂无数据</span>
            ) : (
              <>
                第 <span className="font-semibold text-ink-700">{(safePage - 1) * PAGE_SIZE + 1}</span> -
                <span className="font-semibold text-ink-700">{Math.min(safePage * PAGE_SIZE, filtered.length)}</span> 条，
                共 <span className="font-semibold text-ink-700">{filtered.length}</span> 条
              </>
            )}
          </div>
          <div className="flex items-center gap-1">
            <button
              disabled={safePage <= 1}
              onClick={() => setPage(safePage - 1)}
              className="w-7 h-7 rounded flex items-center justify-center text-ink-500 hover:bg-ink-100 disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
            {pageNumbers.map((p, i) =>
              p === "..." ? (
                <span key={`ellipsis-${i}`} className="text-ink-400 text-xs px-1 select-none">...</span>
              ) : (
                <button
                  key={p}
                  onClick={() => setPage(p)}
                  className={cn(
                    "min-w-[28px] h-7 px-2 rounded text-xs font-medium cursor-pointer transition",
                    p === safePage
                      ? "bg-gradient-to-r from-brand-900 to-brand-700 text-white shadow-sm"
                      : "text-ink-600 hover:bg-ink-100"
                  )}
                >
                  {p}
                </button>
              )
            )}
            <button
              disabled={safePage >= totalPages}
              onClick={() => setPage(safePage + 1)}
              className="w-7 h-7 rounded flex items-center justify-center text-ink-500 hover:bg-ink-100 disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      </Card>

      {/* 新建门店 Modal */}
      <Modal
        open={modalOpen}
        onClose={closeModal}
        title="新增门店"
        size="lg"
        footer={
          <>
            <Button variant="ghost" size="md" onClick={closeModal}>
              取消
            </Button>
            <Button
              variant="gradient"
              size="md"
              onClick={handleSubmit}
              icon={<Plus className="w-4 h-4" />}
            >
              创建门店
            </Button>
          </>
        }
      >
        <div className="space-y-4">
          <div className="flex items-center gap-2 px-3 py-2.5 rounded-lg bg-gradient-to-r from-brand-50/60 to-cyan-50/40 border border-brand-100">
            <Sparkles className="w-4 h-4 text-brand-700 flex-shrink-0" />
            <p className="text-xs text-ink-600">
              新门店将自动加入巡检网络，<span className="font-semibold text-brand-700">暂无评分</span>，完成首次巡检后由巡检记录自动派生综合得分。
            </p>
          </div>

          <Input
            label="门店名称 *"
            placeholder="如：茶小鲜（上海前滩太古里店）"
            value={form.name}
            error={errors.name}
            onChange={(e) => setForm({ ...form, name: e.target.value })}
          />

          <div className="grid grid-cols-2 gap-4">
            <div className="w-full">
              <label className="block text-xs font-medium text-ink-600 mb-1.5">所在城市 *</label>
              <select
                value={form.region}
                onChange={(e) => setForm({ ...form, region: e.target.value })}
                className={cn(
                  "w-full px-3.5 py-2.5 rounded-lg border text-sm transition-all duration-200 outline-none cursor-pointer",
                  "border-ink-200 focus:border-brand-400 focus:ring-2 focus:ring-brand-100 bg-white"
                )}
              >
                {REGIONS.filter((r) => r !== "全部").map((r) => (
                  <option key={r} value={r}>{r}</option>
                ))}
              </select>
              {errors.region && <p className="text-xs text-red-500 mt-1">{errors.region}</p>}
            </div>
            <Input
              label="联系电话 *"
              placeholder="11位手机号"
              value={form.phone}
              error={errors.phone}
              onChange={(e) => setForm({ ...form, phone: e.target.value })}
            />
          </div>

          <Input
            label="店长姓名 *"
            placeholder="如：王芳"
            value={form.manager}
            error={errors.manager}
            onChange={(e) => setForm({ ...form, manager: e.target.value })}
          />

          <div>
            <label className="block text-xs font-medium text-ink-600 mb-1.5">详细地址 *</label>
            <textarea
              placeholder="如：上海市浦东新区前滩太古里石区路 100 号"
              value={form.address}
              onChange={(e) => setForm({ ...form, address: e.target.value })}
              rows={2}
              className={cn(
                "w-full px-3.5 py-2.5 rounded-lg border text-sm transition-all duration-200 outline-none resize-none",
                errors.address
                  ? "border-red-300 focus:border-red-400 focus:ring-2 focus:ring-red-100"
                  : "border-ink-200 focus:border-brand-400 focus:ring-2 focus:ring-brand-100",
                "placeholder:text-ink-300"
              )}
            />
            {errors.address && <p className="text-xs text-red-500 mt-1">{errors.address}</p>}
          </div>

          <div className="text-[11px] text-ink-400 flex items-center gap-1.5 pt-1">
            <Building2 className="w-3 h-3" />
            <span>门店编号将自动生成，开业日期为今日（{new Date().toISOString().slice(0, 10)}）</span>
          </div>
        </div>
      </Modal>
    </div>
  );
}
